class Solution {
public:
    int subsequencesWithMiddleMode(vector<int>& nums) {
        auto nC2 = [](long long n) -> long long {
            return n >= 2 ? n * (n - 1) / 2 : 0;
        };
        const int MOD = 1e9 + 7;
        int n = nums.size();
        if (n < 5) return 0;

        unordered_map<int, int> left, right;
        for (int v : nums) right[v]++;
        long long ans = 0;

        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            right[x]--;

            if (i >= 2 && n - 1 - i >= 2) {
                long long L = i, R = n - 1 - i;
                long long lx = left[x], rx = right[x];
                long long lo = L - lx, ro = R - rx;

                ans += nC2(lx) * nC2(rx);
                ans += nC2(lx) * rx * ro;
                ans += lx * lo * nC2(rx);
                ans += nC2(lx) * nC2(ro);
                ans += nC2(lo) * nC2(rx);
                ans += lx * lo * rx * ro;

                long long waysA = lx * lo * nC2(ro);
                long long badA = 0;
                long long waysB = nC2(lo) * rx * ro;
                long long badB = 0;

                for (const auto& [y, ly] : left) {
                    if (y == x) continue;
                    long long ry = right.count(y) ? right[y] : 0;
                    badA += nC2(ry) * lo + ly * ry * (ro - ry);
                    badB += nC2(ly) * ro + ly * ry * (lo - ly);
                }
                for (const auto& [y, ry] : right) {
                    if (y == x || left.count(y)) continue;
                    long long ly = 0;
                    badA += nC2(ry) * lo + ly * ry * (ro - ry);
                    badB += nC2(ly) * ro + ly * ry * (lo - ly);
                }

                ans += (waysA - badA) + (waysB - badB);
                ans %= MOD;
            }
            left[x]++;
        }
        return (ans % MOD + MOD) % MOD;
    }
};

class Solution {
    private long nC2(long n) {
        return n >= 2 ? n * (n - 1) / 2 : 0;
    }

    public int subsequencesWithMiddleMode(int[] nums) {
        int MOD = 1_000_000_007;
        int n = nums.length;
        if (n < 5) return 0;

        Map<Integer, Integer> left = new HashMap<>();
        Map<Integer, Integer> right = new HashMap<>();
        for (int v : nums) right.put(v, right.getOrDefault(v, 0) + 1);

        long ans = 0;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            right.put(x, right.get(x) - 1);

            if (i >= 2 && n - 1 - i >= 2) {
                long L = i, R = n - 1 - i;
                long lx = left.getOrDefault(x, 0);
                long rx = right.getOrDefault(x, 0);
                long lo = L - lx, ro = R - rx;

                ans += nC2(lx) * nC2(rx);
                ans += nC2(lx) * rx * ro;
                ans += lx * lo * nC2(rx);
                ans += nC2(lx) * nC2(ro);
                ans += nC2(lo) * nC2(rx);
                ans += lx * lo * rx * ro;

                long waysA = lx * lo * nC2(ro);
                long badA = 0;
                long waysB = nC2(lo) * rx * ro;
                long badB = 0;

                Set<Integer> allKeys = new HashSet<>(left.keySet());
                allKeys.addAll(right.keySet());
                for (int y : allKeys) {
                    if (y == x) continue;
                    long ly = left.getOrDefault(y, 0);
                    long ry = right.getOrDefault(y, 0);
                    badA += nC2(ry) * lo + ly * ry * (ro - ry);
                    badB += nC2(ly) * ro + ly * ry * (lo - ly);
                }

                ans += (waysA - badA) + (waysB - badB);
                ans %= MOD;
            }
            left.put(x, left.getOrDefault(x, 0) + 1);
        }
        return (int) ((ans % MOD + MOD) % MOD);
    }
}

